<div class="mb-6"><h1 class="text-2xl font-bold text-white">Plans</h1><p class="text-slate-400 mt-1">Manage VPS plans and pricing tiers</p></div>
<div class="bg-[#13151f] border border-[#2a2d3e] rounded-xl overflow-hidden"><div class="grid grid-cols-7 px-5 py-3 text-xs uppercase tracking-wide text-slate-500 border-b border-[#2a2d3e]"><div>Name</div><div>vCPU</div><div>RAM</div><div>Disk</div><div>BW</div><div>Price</div><div>Type</div></div><?php foreach ($rows as $row): ?><div class="grid grid-cols-7 px-5 py-3 text-sm border-b border-[#1e2130] last:border-0"><div class="font-medium text-white"><?php echo html_escape($row['name']); ?></div><div class="text-slate-400"><?php echo (int) $row['vcpu']; ?></div><div class="text-slate-400"><?php echo (int) $row['memory']; ?> MB</div><div class="text-slate-400"><?php echo (int) $row['disk']; ?> GB</div><div class="text-slate-400"><?php echo (int) $row['bandwidth']; ?> GB</div><div class="text-slate-300">$<?php echo number_format((float) $row['price'], 2); ?></div><div class="uppercase text-xs text-slate-400">KVM</div></div><?php endforeach; ?></div>
